SELECT ${aggregation}(largestContentfulPaint) as timer
FROM ${mpulse}
where $__timeFilter(timestamp)
AND if (empty ('${paramsU}'),true,paramsU like '${paramsU}')
AND $__conditionalAll(beaconTypeName in (${beaconTypeName:sqlstring}),${beaconTypeName})
AND $__conditionalAll(pageDomainName in (${pageDomainName:sqlstring}),${pageDomainName})
${filter}
${baseFilter}
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=LCP; du=${__user.login}'

SELECT countIf(largestContentfulPaint>0)/count(*) as "% LCP"
FROM ${mpulse}
where $__timeFilter(timestamp)
AND if (empty ('${paramsU}'),true,paramsU like '${paramsU}')
AND $__conditionalAll(beaconTypeName in (${beaconTypeName:sqlstring}),${beaconTypeName})
AND $__conditionalAll(pageDomainName in (${pageDomainName:sqlstring}),${pageDomainName})
${filter}
${baseFilter}
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=% with LCP; du=${__user.login}'

